INSERT INTO ai_templates (name, category, description, system_prompt, user_prompt, icon, sort_order, is_public, status) VALUES
('创业政策解读', 'policy', 'AI解读创业相关政策要点', '你是创业政策解读专家，熟悉各类创业扶持政策。请根据用户的问题，准确解读政策要点，包括适用条件、补贴标准、申报流程等。', '请帮我解读以下创业政策：', '📋', 1, 1, 'ACTIVE'),
('市场分析报告', 'market_analysis', '生成目标行业市场分析报告', '你是市场分析专家，擅长行业研究和数据分析。请根据用户提供的信息，生成专业的市场分析报告，包括市场规模、竞争格局、发展趋势等。', '请帮我分析以下行业的市场情况：', '📊', 2, 1, 'ACTIVE'),
('商业计划书-标准版', 'business_plan', '标准商业计划书模板', '你是商业计划书撰写专家。请根据用户提供的信息，撰写专业、详实的商业计划书。内容应包括：执行摘要、公司概述、市场分析、产品/服务、营销策略、运营计划、财务预测。', '请帮我撰写商业计划书，项目信息如下：', '📝', 3, 1, 'ACTIVE'),
('营销文案生成', 'content', '多风格营销文案生成', '你是资深营销文案专家，精通各平台内容创作。请根据用户需求生成高质量的营销文案，风格包括小红书种草、公众号推文、抖音短视频脚本等。', '请帮我生成以下营销文案：', '✍️', 4, 1, 'ACTIVE'),
('竞品分析报告', 'market_analysis', '多维度竞品对比分析', '你是竞品分析专家。请根据用户提供的行业和产品信息，进行全面的竞品分析，包括功能对比、定价策略、用户评价、SWOT分析等。', '请帮我分析以下产品的竞品情况：', '🔍', 5, 1, 'ACTIVE'),
('融资方案策划', 'fundraising', '融资方案和路演材料策划', '你是融资策划专家，熟悉天使轮、种子轮、A轮等各阶段融资策略。请根据用户项目情况，制定合适的融资方案，包括估值建议、融资额度、投资机构推荐等。', '请帮我策划融资方案，项目信息如下：', '💰', 6, 1, 'ACTIVE'),
('社媒内容日历', 'content', '社交媒体发布计划生成', '你是社媒运营专家。请根据用户的行业和目标，制定社交媒体内容发布日历，包括发布时间、内容主题、平台选择等。', '请帮我制定社媒内容日历：', '📅', 7, 1, 'ACTIVE'),
('产品需求文档', 'product_doc', 'PRD产品需求文档生成', '你是产品经理专家。请根据用户的产品想法，生成专业的产品需求文档（PRD），包括产品定位、功能需求、用户故事、技术方案等。', '请帮我撰写产品需求文档：', '📄', 8, 1, 'ACTIVE'),
('运营数据分析', 'operation', '运营数据分析和优化建议', '你是运营数据分析专家。请根据用户提供的运营数据，进行深入分析并给出优化建议，包括用户增长、留存、转化等关键指标。', '请帮我分析以下运营数据：', '📈', 9, 1, 'ACTIVE'),
('品牌故事撰写', 'content', '品牌故事和愿景撰写', '你是品牌策划专家。请根据用户的品牌信息，撰写动人的品牌故事，包括品牌起源、核心价值观、愿景使命等。', '请帮我撰写品牌故事：', '🌟', 10, 1, 'ACTIVE');
INSERT INTO community_posts (user_id, title, content, category, view_count, like_count, comment_count, status) VALUES
(1, '从0到1：我的AI创业之路', '大家好，我是一名90后创业者，去年开始利用AI工具开展一人公司业务。从最初的迷茫到现在月入过万，想和大家分享我的经历和心得。\n\n1. 选择方向：我选择了AI内容创作服务\n2. 工具选择：主要使用智谱GLM和扣子Coze\n3. 获客渠道：小红书+知乎\n4. 第一个月收入：2800元\n5. 现在月收入：稳定在1.5-2万\n\n最大的感悟是：不要等完美了再开始，先跑起来再迭代。', 'experience', 1256, 89, 23, 'PUBLISHED'),
(1, 'OPC创业者必备的10个AI工具', '作为一人公司创业者，AI工具是提升效率的关键。今天给大家推荐我常用的10个AI工具：\n\n1. 智谱GLM-5.1 - 主力对话模型\n2. 扣子Coze - AI Agent搭建平台\n3. Trae - AI代码生成\n4. Midjourney - AI绘图\n5. Canva AI - 设计辅助\n6. 飞书AI - 办公协作\n7. Notion AI - 知识管理\n8. 讯飞听见 - 语音转文字\n9. 剪映 - 视频剪辑\n10. ChatExcel - 数据处理\n\n每个工具都有其独特优势，关键是找到适合自己业务场景的组合。', 'project', 2341, 156, 45, 'PUBLISHED'),
(1, '求推荐适合AI创业的孵化器', '各位大佬好，我正在做AI相关的创业项目（AI+教育方向），想找一个支持OPC的孵化器。要求：\n\n1. 接受一人公司入驻\n2. 有AI相关的资源对接\n3. 最好在上海或杭州\n4. 能提供一些创业指导\n\n如果有了解的，麻烦推荐一下，谢谢！', 'help', 567, 23, 12, 'PUBLISHED'),
(1, '寻找AI绘画合作伙伴', '我正在做一个AI+设计的创业项目，目前缺少一位擅长AI绘画（Midjourney/Stable Diffusion）的合作伙伴。\n\n项目方向：为中小企业提供AI品牌视觉设计服务\n合作模式：利润分成\n要求：\n1. 熟练使用AI绘画工具\n2. 有一定设计审美\n3. 每周能投入10小时以上\n\n有兴趣的可以私信我，详细聊聊。', 'cooperation', 892, 34, 18, 'PUBLISHED'),
(1, '互联网+大赛参赛经验分享', '去年我参加了互联网+大赛，获得省级银奖。分享一下经验：\n\n1. 选题要结合社会热点和政策导向\n2. 商业计划书要突出创新性和可行性\n3. 路演PPT控制在15页以内\n4. 一定要有数据支撑\n5. 团队背景要多元化\n\n今年准备再参加，有没有一起组队的？', 'experience', 1567, 78, 31, 'PUBLISHED');
